    privacyP2c: "acopay.org verwendet lokalen Speicher (und ggf. notwendige Cookies) nur soweit erforderlich, um Sprach- und Designeinstellungen zu speichern und grundlegende Website-Funktionen aufrechtzuerhalten. Zum oben genannten Datum setzen wir auf dieser Website keine Werbe-Analyse-SDKs ein. Übliche technische Protokolle können weiterhin durch Hosting- und Sicherheitsinfrastruktur verarbeitet werden.",
    privacyH2d: "2.4. Öffentliche Blockchain-Daten",
